\[
\begin{array}{l} \frac {f (b) - f (a)}{b - a} = \frac {6 9 - 8 5}{7 - 3} = \frac {- 1 6}{4} = - 4 \\ \text { MVT } \quad \frac {7 + 3}{2} = 1 0 \quad c ^ {\prime} (5) \approx - 4 \text { degrees } c ^ {\circ} / \text { minute } \\ \end{array}
\]

